# One-off (Nov 2026): wove the real platform facts from Pradeep's Cursor answers into existing answers. Already applied; do not re-run.
import re,glob
files={f:open(f).read().split('\n') for f in sorted(glob.glob('enrich/*.txt'))}
def lines_of(id):
    out=[]
    for f,L in files.items():
        cur=None
        for i,l in enumerate(L):
            m=re.match(r'^\+?@(\S+)\s*$',l)
            if m: cur=m.group(1); continue
            if cur==id and l.startswith(('X: ','Y: ')): out.append((f,i))
    return out
def weave(id,old,new):
    hits=[(f,i) for f,i in lines_of(id) if old in files[f][i]]
    assert hits,(id,old)
    f,i=hits[0]; files[f][i]=files[f][i].replace(old,new,1)
def W(id,old,new): weave(id,old,new)
